<!doctype html><html><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans,sans-serif;font-size:11px;color:#172033}h1,h2{color:#12305c}table{width:100%;border-collapse:collapse;margin:12px 0}th,td{border:1px solid #d9e1ee;padding:7px;text-align:left}th{background:#edf2fa}.right{text-align:right}.muted{color:#65748b}.box{border:1px solid #d9e1ee;padding:10px;margin:10px 0;white-space:pre-wrap}.total{font-size:15px;font-weight:bold}</style></head><body><h1>FYNTRIC TECH IT SOLUTIONS</h1><p class="muted">Project Quotation & Statement of Work</p><hr><h2>Quotation <?= html_escape($q['quote_number']) ?></h2><p><b>Client:</b> <?= html_escape($q['company_name']) ?><br><b>Contact:</b> <?= html_escape($q['contact_name']) ?><br><b>Project:</b> <?= html_escape($q['project_title']) ?> (<?= html_escape($q['project_code']) ?>)<br><b>Issue date:</b> <?= html_escape($q['issue_date']) ?> &nbsp; <b>Valid until:</b> <?= html_escape($q['valid_until']) ?></p><table><thead><tr><th>Description</th><th>Qty</th><th>Unit price</th><th>Amount</th></tr></thead><tbody><?php foreach($items as $i): ?><tr><td><?= html_escape($i['description']) ?></td><td><?= number_format($i['quantity'],2) ?></td><td><?= html_escape($q['currency']) ?> <?= number_format($i['unit_price'],2) ?></td><td><?= html_escape($q['currency']) ?> <?= number_format($i['line_total'],2) ?></td></tr><?php endforeach; ?></tbody></table><p class="right">Subtotal: <?= html_escape($q['currency']) ?> <?= number_format($q['subtotal'],2) ?><br>Tax (<?= number_format($q['tax_rate'],3) ?>%): <?= html_escape($q['currency']) ?> <?= number_format($q['tax_amount'],2) ?><br><span class="total">Total: <?= html_escape($q['currency']) ?> <?= number_format($q['total_amount'],2) ?></span></p><h3>Statement of Work</h3><div class="box"><?= html_escape($q['scope_summary']) ?></div><h4>Exclusions</h4><div class="box"><?= html_escape($q['exclusions']) ?></div><p><b>Timeline:</b> <?= html_escape($q['timeline_text']) ?></p><h3>Payment Milestones</h3><table><thead><tr><th>Milestone</th><th>Percent</th><th>Amount</th><th>Trigger</th></tr></thead><tbody><?php foreach($milestones as $m): ?><tr><td><?= html_escape($m['title']) ?></td><td><?= number_format($m['percentage'],2) ?>%</td><td><?= html_escape($q['currency']) ?> <?= number_format($m['amount'],2) ?></td><td><?= html_escape($m['due_trigger']) ?></td></tr><?php endforeach; ?></tbody></table><h3>Terms & Conditions</h3><div class="box"><?= html_escape($q['terms']) ?></div><p class="muted">GST/tax is calculated according to the tax rate entered in this quotation. Both parties should retain a signed/approved copy.</p><br><table><tr><td style="height:55px">For Fyntric Tech IT Solutions<br><br>Authorized signature: __________________</td><td>For the Client<br><br>Authorized signature: __________________</td></tr></table></body></html>
